/**********************************************************************************
Criar stored procedure [dbo].[CategoriesRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[CategoriesRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[CategoriesRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[CategoriesRead](@Login NVARCHAR(MAX)
                                          ,@RecordFilterGrid NVARCHAR(MAX)
                                          ,@RecordFilterTable NVARCHAR(MAX)
                                          ,@RecordSearch NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @LoginId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @LoginId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @LoginId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    IF @RecordFilterGrid IS NULL
            SET @RecordFilterGrid = '{}'
        ELSE IF ISJSON(@RecordFilterGrid) = 0
            THROW 51000, 'Valor de @RecordFilterGrid não está no formato JSON', 1
        IF @RecordFilterTable IS NULL
            SET @RecordFilterTable = '{}'
        ELSE IF ISJSON(@RecordFilterTable) = 0
            THROW 51000, 'Valor de @RecordFilterTable não está no formato JSON', 1
        IF @RecordSearch IS NOT NULL AND ISJSON(@RecordSearch) = 0
            THROW 51000, 'Valor de @RecordSearch não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Categories') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
            IF CHARINDEX('[T].[Id]', @OrderBy) = 0
                SET @OrderBy = @OrderBy + ', [T].[Id] ASC'
        END
        IF @IsActionList = 1
            SET @OrderBy = '[T].[Name] ASC, [T].[Id] ASC'
        DECLARE @PickerValue nvarchar(25) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @LoginId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) AS [Id]
              ,CAST([dbo].[NUMBER_IN_WORDS](CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint)) AS NVARCHAR(MAX)) AS [IdInWords]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(25)) AS [Name]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.HtmlInputType') AS nvarchar(10)) AS [HtmlInputType]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.HtmlInputAlign') AS nvarchar(6)) AS [HtmlInputAlign]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskEncrypted') AS bit) AS [AskEncrypted]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskMask') AS bit) AS [AskMask]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskListable') AS bit) AS [AskListable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskDefault') AS bit) AS [AskDefault]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskMinimum') AS bit) AS [AskMinimum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskMaximum') AS bit) AS [AskMaximum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskInWords') AS bit) AS [AskInWords]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Categories'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@RecordFilterGrid, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id tinyint = CAST(JSON_VALUE(@RecordFilterTable, '$.Id') AS tinyint)
               ,@WT_Name nvarchar(25) = CAST(JSON_VALUE(@RecordFilterTable, '$.Name') AS nvarchar(25))
               ,@WT_AskEncrypted bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskEncrypted') AS bit)
               ,@WT_AskMask bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskMask') AS bit)
               ,@WT_AskListable bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskListable') AS bit)
               ,@WT_AskDefault bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskDefault') AS bit)
               ,@WT_AskMinimum bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskMinimum') AS bit)
               ,@WT_AskMaximum bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskMaximum') AS bit)
               ,@WT_AskInWords bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskInWords') AS bit)

        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Id' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Id] IS NULL'
        ELSE IF @WT_Id IS NOT NULL BEGIN
            IF @WT_Id < CAST('1' AS tinyint)
                THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Name' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Name] IS NULL'
        ELSE IF @WT_Name IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Name] = @T_Name'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskEncrypted' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskEncrypted] IS NULL'
        ELSE IF @WT_AskEncrypted IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskEncrypted] = @T_AskEncrypted'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskMask' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskMask] IS NULL'
        ELSE IF @WT_AskMask IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskMask] = @T_AskMask'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskListable' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskListable] IS NULL'
        ELSE IF @WT_AskListable IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskListable] = @T_AskListable'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskDefault' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskDefault] IS NULL'
        ELSE IF @WT_AskDefault IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskDefault] = @T_AskDefault'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskMinimum' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskMinimum] IS NULL'
        ELSE IF @WT_AskMinimum IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskMinimum] = @T_AskMinimum'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskMaximum' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskMaximum] IS NULL'
        ELSE IF @WT_AskMaximum IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskMaximum] = @T_AskMaximum'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskInWords' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskInWords] IS NULL'
        ELSE IF @WT_AskInWords IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskInWords] = @T_AskInWords'
        END
        IF @IsActionList = 1 BEGIN
            SET @PickerValue = CAST(JSON_VALUE(@RecordFilterGrid, '$.Picker.Value') AS nvarchar(25))
            IF @PickerValue IS NULL
                SET @PickerValue = ''
            SET @Where = @Where + ' AND [T].[Name] LIKE ''%'' + @PickerValue + ''%'''
        END ELSE IF @_ IS NULL BEGIN
            DECLARE @W_Id tinyint = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.Id') AS tinyint), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.Id') AS tinyint), CAST(JSON_VALUE(@RecordFilterGrid, '$.Id') AS tinyint))
                   ,@W_Name nvarchar(25) = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.Name') AS nvarchar(25)), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.Name') AS nvarchar(25)), CAST(JSON_VALUE(@RecordFilterGrid, '$.Name') AS nvarchar(25)))
                   ,@W_AskEncrypted bit = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.AskEncrypted') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.AskEncrypted') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.AskEncrypted') AS bit))
                   ,@W_AskMask bit = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.AskMask') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.AskMask') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.AskMask') AS bit))
                   ,@W_AskListable bit = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.AskListable') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.AskListable') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.AskListable') AS bit))
                   ,@W_AskDefault bit = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.AskDefault') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.AskDefault') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.AskDefault') AS bit))
                   ,@W_AskMinimum bit = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.AskMinimum') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.AskMinimum') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.AskMinimum') AS bit))
                   ,@W_AskMaximum bit = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.AskMaximum') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.AskMaximum') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.AskMaximum') AS bit))
                   ,@W_AskInWords bit = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.AskInWords') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.AskInWords') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.AskInWords') AS bit))

            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'Id' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[Id] IS NULL'
            ELSE IF @W_Id IS NOT NULL BEGIN
                IF @W_Id < CAST('1' AS tinyint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @Where = @Where + ' AND [T].[Id] = @Id'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'Name' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'Name' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Name' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'Name' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[Name] IS NULL'
            ELSE IF @W_Name IS NOT NULL BEGIN
                SET @Where = @Where + ' AND [T].[Name] = @Name'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'AskEncrypted' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'AskEncrypted' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskEncrypted' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'AskEncrypted' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[AskEncrypted] IS NULL'
            ELSE IF @W_AskEncrypted IS NOT NULL BEGIN
                SET @Where = @Where + ' AND [T].[AskEncrypted] = @AskEncrypted'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'AskMask' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'AskMask' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskMask' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'AskMask' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[AskMask] IS NULL'
            ELSE IF @W_AskMask IS NOT NULL BEGIN
                SET @Where = @Where + ' AND [T].[AskMask] = @AskMask'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'AskListable' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'AskListable' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskListable' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'AskListable' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[AskListable] IS NULL'
            ELSE IF @W_AskListable IS NOT NULL BEGIN
                SET @Where = @Where + ' AND [T].[AskListable] = @AskListable'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'AskDefault' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'AskDefault' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskDefault' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'AskDefault' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[AskDefault] IS NULL'
            ELSE IF @W_AskDefault IS NOT NULL BEGIN
                SET @Where = @Where + ' AND [T].[AskDefault] = @AskDefault'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'AskMinimum' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'AskMinimum' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskMinimum' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'AskMinimum' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[AskMinimum] IS NULL'
            ELSE IF @W_AskMinimum IS NOT NULL BEGIN
                SET @Where = @Where + ' AND [T].[AskMinimum] = @AskMinimum'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'AskMaximum' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'AskMaximum' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskMaximum' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'AskMaximum' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[AskMaximum] IS NULL'
            ELSE IF @W_AskMaximum IS NOT NULL BEGIN
                SET @Where = @Where + ' AND [T].[AskMaximum] = @AskMaximum'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'AskInWords' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'AskInWords' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'AskInWords' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'AskInWords' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[AskInWords] IS NULL'
            ELSE IF @W_AskInWords IS NOT NULL BEGIN
                SET @Where = @Where + ' AND [T].[AskInWords] = @AskInWords'
            END
        END ELSE
            SET @Where = @Where + ' AND [T].[Id] IN (' + @_ + ')'
        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] tinyint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                                        ,[T].[Id]
                                    FROM [dbo].[Categories] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [#].[Id] = [T].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                                        ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @IsActionList = 1 BEGIN
            EXEC sp_executesql @sql
                               ,N'@PickerValue nvarchar(25),@T_Id tinyint,@T_Name nvarchar(25),@T_AskEncrypted bit,@T_AskMask bit,@T_AskListable bit,@T_AskDefault bit,@T_AskMinimum bit,@T_AskMaximum bit,@T_AskInWords bit'
                               ,@PickerValue = @PickerValue
                               ,@T_Id = @WT_Id
                               ,@T_Name = @WT_Name
                               ,@T_AskEncrypted = @WT_AskEncrypted
                               ,@T_AskMask = @WT_AskMask
                               ,@T_AskListable = @WT_AskListable
                               ,@T_AskDefault = @WT_AskDefault
                               ,@T_AskMinimum = @WT_AskMinimum
                               ,@T_AskMaximum = @WT_AskMaximum
                               ,@T_AskInWords = @WT_AskInWords
        END ELSE IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id tinyint,@T_Name nvarchar(25),@T_AskEncrypted bit,@T_AskMask bit,@T_AskListable bit,@T_AskDefault bit,@T_AskMinimum bit,@T_AskMaximum bit,@T_AskInWords bit,@Id tinyint,@Name nvarchar(25),@AskEncrypted bit,@AskMask bit,@AskListable bit,@AskDefault bit,@AskMinimum bit,@AskMaximum bit,@AskInWords bit'
                               ,@T_Id = @WT_Id
                               ,@T_Name = @WT_Name
                               ,@T_AskEncrypted = @WT_AskEncrypted
                               ,@T_AskMask = @WT_AskMask
                               ,@T_AskListable = @WT_AskListable
                               ,@T_AskDefault = @WT_AskDefault
                               ,@T_AskMinimum = @WT_AskMinimum
                               ,@T_AskMaximum = @WT_AskMaximum
                               ,@T_AskInWords = @WT_AskInWords
                               ,@Id = @W_Id
                               ,@Name = @W_Name
                               ,@AskEncrypted = @W_AskEncrypted
                               ,@AskMask = @W_AskMask
                               ,@AskListable = @W_AskListable
                               ,@AskDefault = @W_AskDefault
                               ,@AskMinimum = @W_AskMinimum
                               ,@AskMaximum = @W_AskMaximum
                               ,@AskInWords = @W_AskInWords
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id tinyint,@T_Name nvarchar(25),@T_AskEncrypted bit,@T_AskMask bit,@T_AskListable bit,@T_AskDefault bit,@T_AskMinimum bit,@T_AskMaximum bit,@T_AskInWords bit'
                               ,@T_Id = @WT_Id
                               ,@T_Name = @WT_Name
                               ,@T_AskEncrypted = @WT_AskEncrypted
                               ,@T_AskMask = @WT_AskMask
                               ,@T_AskListable = @WT_AskListable
                               ,@T_AskDefault = @WT_AskDefault
                               ,@T_AskMinimum = @WT_AskMinimum
                               ,@T_AskMaximum = @WT_AskMaximum
                               ,@T_AskInWords = @WT_AskInWords
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            DECLARE @SearchRecno BIGINT = NULL
            IF @RecordSearch IS NOT NULL BEGIN
                DECLARE @Recno BIGINT
                       ,@S_Id tinyint = CAST(JSON_VALUE(@RecordSearch, '$.Id') AS tinyint)
                       ,@S_Name nvarchar(25) = CAST(JSON_VALUE(@RecordSearch, '$.Name') AS nvarchar(25))
                       ,@S_AskEncrypted bit = CAST(JSON_VALUE(@RecordSearch, '$.AskEncrypted') AS bit)
                       ,@S_AskMask bit = CAST(JSON_VALUE(@RecordSearch, '$.AskMask') AS bit)
                       ,@S_AskListable bit = CAST(JSON_VALUE(@RecordSearch, '$.AskListable') AS bit)
                       ,@S_AskDefault bit = CAST(JSON_VALUE(@RecordSearch, '$.AskDefault') AS bit)
                       ,@S_AskMinimum bit = CAST(JSON_VALUE(@RecordSearch, '$.AskMinimum') AS bit)
                       ,@S_AskMaximum bit = CAST(JSON_VALUE(@RecordSearch, '$.AskMaximum') AS bit)
                       ,@S_AskInWords bit = CAST(JSON_VALUE(@RecordSearch, '$.AskInWords') AS bit)

                SET @Where = ''
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'Id' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Id], [O].[Id]) IS NULL'
                ELSE IF @S_Id IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Id], [O].[Id]) = @Id'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'Name' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Name], [O].[Name]) IS NULL'
                ELSE IF @S_Name IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Name], [O].[Name]) LIKE ''%'' + @Name + ''%'''
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'AskEncrypted' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskEncrypted], [O].[AskEncrypted]) IS NULL'
                ELSE IF @S_AskEncrypted IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskEncrypted], [O].[AskEncrypted]) = @AskEncrypted'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'AskMask' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskMask], [O].[AskMask]) IS NULL'
                ELSE IF @S_AskMask IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskMask], [O].[AskMask]) = @AskMask'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'AskListable' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskListable], [O].[AskListable]) IS NULL'
                ELSE IF @S_AskListable IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskListable], [O].[AskListable]) = @AskListable'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'AskDefault' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskDefault], [O].[AskDefault]) IS NULL'
                ELSE IF @S_AskDefault IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskDefault], [O].[AskDefault]) = @AskDefault'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'AskMinimum' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskMinimum], [O].[AskMinimum]) IS NULL'
                ELSE IF @S_AskMinimum IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskMinimum], [O].[AskMinimum]) = @AskMinimum'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'AskMaximum' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskMaximum], [O].[AskMaximum]) IS NULL'
                ELSE IF @S_AskMaximum IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskMaximum], [O].[AskMaximum]) = @AskMaximum'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'AskInWords' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskInWords], [O].[AskInWords]) IS NULL'
                ELSE IF @S_AskInWords IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[AskInWords], [O].[AskInWords]) = @AskInWords'
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Categories] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id tinyint,@Name nvarchar(25),@AskEncrypted bit,@AskMask bit,@AskListable bit,@AskDefault bit,@AskMinimum bit,@AskMaximum bit,@AskInWords bit, @r BIGINT OUTPUT'
                                       ,@Id = @S_Id
                                       ,@Name = @S_Name
                                       ,@AskEncrypted = @S_AskEncrypted
                                       ,@AskMask = @S_AskMask
                                       ,@AskListable = @S_AskListable
                                       ,@AskDefault = @S_AskDefault
                                       ,@AskMinimum = @S_AskMinimum
                                       ,@AskMaximum = @S_AskMaximum
                                       ,@AskInWords = @S_AskInWords
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS tinyint) AS [Id]
                    ,CAST(NULL AS NVARCHAR(MAX)) AS [IdInWords]
                    ,CAST(NULL AS nvarchar(25)) AS [Name]
                    ,CAST(NULL AS nvarchar(10)) AS [HtmlInputType]
                    ,CAST(NULL AS nvarchar(6)) AS [HtmlInputAlign]
                    ,CAST(NULL AS bit) AS [AskEncrypted]
                    ,CAST(NULL AS bit) AS [AskMask]
                    ,CAST(NULL AS bit) AS [AskListable]
                    ,CAST(NULL AS bit) AS [AskDefault]
                    ,CAST(NULL AS bit) AS [AskMinimum]
                    ,CAST(NULL AS bit) AS [AskMaximum]
                    ,CAST(NULL AS bit) AS [AskInWords]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Category'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,CAST([dbo].[NUMBER_IN_WORDS](CAST([T].[Id] AS tinyint)) AS NVARCHAR(MAX)) AS [IdInWords]
                              ,[T].[Name]
                              ,[T].[HtmlInputType]
                              ,[T].[HtmlInputAlign]
                              ,[T].[AskEncrypted]
                              ,[T].[AskMask]
                              ,[T].[AskListable]
                              ,[T].[AskDefault]
                              ,[T].[AskMinimum]
                              ,[T].[AskMaximum]
                              ,[T].[AskInWords]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Categories] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Category'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,CAST([dbo].[NUMBER_IN_WORDS](CAST([O].[Id] AS tinyint)) AS NVARCHAR(MAX)) AS [IdInWords]
                                  ,[O].[Name]
                                  ,[O].[HtmlInputType]
                                  ,[O].[HtmlInputAlign]
                                  ,[O].[AskEncrypted]
                                  ,[O].[AskMask]
                                  ,[O].[AskListable]
                                  ,[O].[AskDefault]
                                  ,[O].[AskMinimum]
                                  ,[O].[AskMaximum]
                                  ,[O].[AskInWords]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[IdInWords]
                      ,[Name]
                      ,[Name] AS [ListItemValue]
                      ,[HtmlInputType]
                      ,[HtmlInputAlign]
                      ,[AskEncrypted]
                      ,[AskMask]
                      ,[AskListable]
                      ,[AskDefault]
                      ,[AskMinimum]
                      ,[AskMaximum]
                      ,[AskInWords]
                    FROM [#result] FOR JSON PATH) AS [result]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TypeValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TypeValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TypeValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TypeValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS tinyint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS tinyint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS tinyint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS tinyint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Types] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em Types', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Types'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em Types', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Types]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [CategoryId] = JSON_VALUE(@LastRecord, '$.CategoryId')
                                  AND [Name] = JSON_VALUE(@LastRecord, '$.Name')
                                  AND [dbo].[IS_EQUAL]([MaxLength], JSON_VALUE(@LastRecord, '$.MaxLength'), 'int') = 1
                                  AND [dbo].[IS_EQUAL]([Minimum], JSON_VALUE(@LastRecord, '$.Minimum'), 'nvarchar(max)') = 1
                                  AND [dbo].[IS_EQUAL]([Maximum], JSON_VALUE(@LastRecord, '$.Maximum'), 'nvarchar(max)') = 1
                                  AND [AskLength] = JSON_VALUE(@LastRecord, '$.AskLength')
                                  AND [AskDecimals] = JSON_VALUE(@LastRecord, '$.AskDecimals')
                                  AND [AskPrimarykey] = JSON_VALUE(@LastRecord, '$.AskPrimarykey')
                                  AND [AskAutoincrement] = JSON_VALUE(@LastRecord, '$.AskAutoincrement')
                                  AND [AskFilterable] = JSON_VALUE(@LastRecord, '$.AskFilterable')
                                  AND [AskGridable] = JSON_VALUE(@LastRecord, '$.AskGridable')
                                  AND [AskCodification] = JSON_VALUE(@LastRecord, '$.AskCodification')
                                  AND [IsLikeable] = JSON_VALUE(@LastRecord, '$.IsLikeable')
                                  AND [IsActive] = JSON_VALUE(@LastRecord, '$.IsActive'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Types'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.CategoryId') = JSON_VALUE(@LastRecord, '$.CategoryId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') = JSON_VALUE(@LastRecord, '$.Name')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.MaxLength'), JSON_VALUE(@LastRecord, '$.MaxLength'), 'int') = 1
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Minimum'), JSON_VALUE(@LastRecord, '$.Minimum'), 'nvarchar(max)') = 1
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Maximum'), JSON_VALUE(@LastRecord, '$.Maximum'), 'nvarchar(max)') = 1
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskLength') = JSON_VALUE(@LastRecord, '$.AskLength')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskDecimals') = JSON_VALUE(@LastRecord, '$.AskDecimals')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskPrimarykey') = JSON_VALUE(@LastRecord, '$.AskPrimarykey')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskAutoincrement') = JSON_VALUE(@LastRecord, '$.AskAutoincrement')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskFilterable') = JSON_VALUE(@LastRecord, '$.AskFilterable')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskGridable') = JSON_VALUE(@LastRecord, '$.AskGridable')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskCodification') = JSON_VALUE(@LastRecord, '$.AskCodification')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsLikeable') = JSON_VALUE(@LastRecord, '$.IsLikeable')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsActive') = JSON_VALUE(@LastRecord, '$.IsActive'))
                THROW 51000, 'Registro de Types alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[Domains] WHERE [TypeId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Domains', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_CategoryId tinyint = CAST(JSON_VALUE(@ActualRecord, '$.CategoryId') AS tinyint)
                   ,@W_Name nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(25))
                   ,@W_MaxLength int = CAST(JSON_VALUE(@ActualRecord, '$.MaxLength') AS int)
                   ,@W_Minimum nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.Minimum') AS nvarchar(max))
                   ,@W_Maximum nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.Maximum') AS nvarchar(max))
                   ,@W_AskLength bit = CAST(JSON_VALUE(@ActualRecord, '$.AskLength') AS bit)
                   ,@W_AskDecimals bit = CAST(JSON_VALUE(@ActualRecord, '$.AskDecimals') AS bit)
                   ,@W_AskPrimarykey bit = CAST(JSON_VALUE(@ActualRecord, '$.AskPrimarykey') AS bit)
                   ,@W_AskAutoincrement bit = CAST(JSON_VALUE(@ActualRecord, '$.AskAutoincrement') AS bit)
                   ,@W_AskFilterable bit = CAST(JSON_VALUE(@ActualRecord, '$.AskFilterable') AS bit)
                   ,@W_AskGridable bit = CAST(JSON_VALUE(@ActualRecord, '$.AskGridable') AS bit)
                   ,@W_AskCodification bit = CAST(JSON_VALUE(@ActualRecord, '$.AskCodification') AS bit)
                   ,@W_IsLikeable bit = CAST(JSON_VALUE(@ActualRecord, '$.IsLikeable') AS bit)
                   ,@W_IsActive bit = CAST(JSON_VALUE(@ActualRecord, '$.IsActive') AS bit)

            IF @W_CategoryId IS NULL
                THROW 51000, 'Valor de CategoryId em @ActualRecord é requerido.', 1
            IF NOT EXISTS(SELECT 1 FROM [dbo].[Categories] WHERE [Id] = @W_CategoryId)
                THROW 51000, 'Valor de CategoryId em @ActualRecord inexiste em Categories', 1
            IF @W_Name IS NULL
                THROW 51000, 'Valor de Name em @ActualRecord é requerido.', 1
            IF @W_MaxLength IS NOT NULL AND @W_MaxLength < CAST('1' AS int)
                THROW 51000, 'Valor de MaxLength em @ActualRecord deve ser maior que ou igual a 1', 1
            IF @W_AskLength IS NULL
                THROW 51000, 'Valor de AskLength em @ActualRecord é requerido.', 1
            IF @W_AskDecimals IS NULL
                THROW 51000, 'Valor de AskDecimals em @ActualRecord é requerido.', 1
            IF @W_AskPrimarykey IS NULL
                THROW 51000, 'Valor de AskPrimarykey em @ActualRecord é requerido.', 1
            IF @W_AskAutoincrement IS NULL
                THROW 51000, 'Valor de AskAutoincrement em @ActualRecord é requerido.', 1
            IF @W_AskFilterable IS NULL
                THROW 51000, 'Valor de AskFilterable em @ActualRecord é requerido.', 1
            IF @W_AskGridable IS NULL
                THROW 51000, 'Valor de AskGridable em @ActualRecord é requerido.', 1
            IF @W_AskCodification IS NULL
                THROW 51000, 'Valor de AskCodification em @ActualRecord é requerido.', 1
            IF @W_IsLikeable IS NULL
                THROW 51000, 'Valor de IsLikeable em @ActualRecord é requerido.', 1
            IF @W_IsActive IS NULL
                THROW 51000, 'Valor de IsActive em @ActualRecord é requerido.', 1
            IF @Action = 'create' BEGIN
                IF EXISTS(SELECT 1 FROM [dbo].[Types] WHERE [Name] = @W_Name)
                    THROW 51000, 'Chave única de UNQ_Types_Name já existe', 1
            ELSE IF EXISTS(SELECT 1 FROM [dbo].[Types] WHERE [Name] = @W_Name AND [Id] <> @W_Id)
                THROW 51000, 'Chave única de UNQ_Types_Name já existe', 1
            END
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TypePersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TypePersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TypePersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TypePersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id tinyint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS tinyint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS tinyint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS tinyint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Types'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Types', @NewId OUT
            SET @W_Id = CAST(@NewId AS tinyint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[TypeValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Types'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Types'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[TypeValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

