               ,@W_AskFilterable bit = CAST(JSON_VALUE(@ActualRecord, '$.AskFilterable') AS bit)
               ,@W_AskGridable bit = CAST(JSON_VALUE(@ActualRecord, '$.AskGridable') AS bit)
               ,@W_AskCodification bit = CAST(JSON_VALUE(@ActualRecord, '$.AskCodification') AS bit)
               ,@W_IsLikeable bit = CAST(JSON_VALUE(@ActualRecord, '$.IsLikeable') AS bit)
               ,@W_IsActive bit = CAST(JSON_VALUE(@ActualRecord, '$.IsActive') AS bit)

        INSERT INTO [dbo].[Types] ([Id]
                                            ,[CategoryId]
                                            ,[Name]
                                            ,[MaxLength]
                                            ,[Minimum]
                                            ,[Maximum]
                                            ,[AskLength]
                                            ,[AskDecimals]
                                            ,[AskPrimarykey]
                                            ,[AskAutoincrement]
                                            ,[AskFilterable]
                                            ,[AskGridable]
                                            ,[AskCodification]
                                            ,[IsLikeable]
                                            ,[IsActive]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_CategoryId
                                             ,@W_Name
                                             ,@W_MaxLength
                                             ,@W_Minimum
                                             ,@W_Maximum
                                             ,@W_AskLength
                                             ,@W_AskDecimals
                                             ,@W_AskPrimarykey
                                             ,@W_AskAutoincrement
                                             ,@W_AskFilterable
                                             ,@W_AskGridable
                                             ,@W_AskCodification
                                             ,@W_IsLikeable
                                             ,@W_IsActive
                                             ,GETDATE()
                                             ,@UserName)
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

