/**********************************************************************************
Criar stored procedure [dbo].[TypesRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TypesRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TypesRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TypesRead](@Login NVARCHAR(MAX)
                                          ,@RecordFilterGrid NVARCHAR(MAX)
                                          ,@RecordFilterTable NVARCHAR(MAX)
                                          ,@RecordSearch NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @LoginId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @LoginId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @LoginId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    IF @RecordFilterGrid IS NULL
            SET @RecordFilterGrid = '{}'
        ELSE IF ISJSON(@RecordFilterGrid) = 0
            THROW 51000, 'Valor de @RecordFilterGrid não está no formato JSON', 1
        IF @RecordFilterTable IS NULL
            SET @RecordFilterTable = '{}'
        ELSE IF ISJSON(@RecordFilterTable) = 0
            THROW 51000, 'Valor de @RecordFilterTable não está no formato JSON', 1
        IF @RecordSearch IS NOT NULL AND ISJSON(@RecordSearch) = 0
            THROW 51000, 'Valor de @RecordSearch não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Types') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
            IF CHARINDEX('[T].[Id]', @OrderBy) = 0
                SET @OrderBy = @OrderBy + ', [T].[Id] ASC'
        END
        IF @IsActionList = 1
            SET @OrderBy = '[T].[Name] ASC, [T].[Id] ASC'
        DECLARE @PickerValue nvarchar(25) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @LoginId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.CategoryId') AS tinyint) AS [CategoryId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(25)) AS [Name]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.MaxLength') AS int) AS [MaxLength]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Minimum') AS nvarchar(max)) AS [Minimum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Maximum') AS nvarchar(max)) AS [Maximum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskLength') AS bit) AS [AskLength]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskDecimals') AS bit) AS [AskDecimals]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskPrimarykey') AS bit) AS [AskPrimarykey]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskAutoincrement') AS bit) AS [AskAutoincrement]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskFilterable') AS bit) AS [AskFilterable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskGridable') AS bit) AS [AskGridable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskCodification') AS bit) AS [AskCodification]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsLikeable') AS bit) AS [IsLikeable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsActive') AS bit) AS [IsActive]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Types'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@RecordFilterGrid, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id tinyint = CAST(JSON_VALUE(@RecordFilterTable, '$.Id') AS tinyint)
               ,@WT_Name nvarchar(25) = CAST(JSON_VALUE(@RecordFilterTable, '$.Name') AS nvarchar(25))
               ,@WT_AskLength bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskLength') AS bit)
               ,@WT_AskDecimals bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskDecimals') AS bit)
               ,@WT_AskPrimarykey bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskPrimarykey') AS bit)
               ,@WT_AskAutoincrement bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskAutoincrement') AS bit)
               ,@WT_AskFilterable bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskFilterable') AS bit)
               ,@WT_AskGridable bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskGridable') AS bit)
               ,@WT_AskCodification bit = CAST(JSON_VALUE(@RecordFilterTable, '$.AskCodification') AS bit)
               ,@WT_IsLikeable bit = CAST(JSON_VALUE(@RecordFilterTable, '$.IsLikeable') AS bit)
               ,@WT_IsActive bit = CAST(JSON_VALUE(@RecordFilterTable, '$.IsActive') AS bit)

        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Id' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Id] IS NULL'
        ELSE IF @WT_Id IS NOT NULL BEGIN
            IF @WT_Id < CAST('1' AS tinyint)
