                       ,@S_IsEditable bit = CAST(JSON_VALUE(@RecordSearch, '$.IsEditable') AS bit)
                       ,@S_IsGridable bit = CAST(JSON_VALUE(@RecordSearch, '$.IsGridable') AS bit)
                       ,@S_IsEncrypted bit = CAST(JSON_VALUE(@RecordSearch, '$.IsEncrypted') AS bit)
                       ,@S_IsInWords bit = CAST(JSON_VALUE(@RecordSearch, '$.IsInWords') AS bit)

                SET @Where = ''
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'Id' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Id], [O].[Id]) IS NULL'
                ELSE IF @S_Id IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Id], [O].[Id]) = @Id'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'TableId' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[TableId], [O].[TableId]) IS NULL'
                ELSE IF @S_TableId IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[TableId], [O].[TableId]) = @TableId'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'DomainId' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[DomainId], [O].[DomainId]) IS NULL'
                ELSE IF @S_DomainId IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[DomainId], [O].[DomainId]) = @DomainId'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'ReferenceTableId' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[ReferenceTableId], [O].[ReferenceTableId]) IS NULL'
                ELSE IF @S_ReferenceTableId IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[ReferenceTableId], [O].[ReferenceTableId]) = @ReferenceTableId'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'Name' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Name], [O].[Name]) IS NULL'
                ELSE IF @S_Name IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Name], [O].[Name]) LIKE ''%'' + @Name + ''%'''
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'Alias' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Alias], [O].[Alias]) IS NULL'
                ELSE IF @S_Alias IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Alias], [O].[Alias]) LIKE ''%'' + @Alias + ''%'''
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'IsAutoIncrement' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsAutoIncrement], [O].[IsAutoIncrement]) IS NULL'
                ELSE IF @S_IsAutoIncrement IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsAutoIncrement], [O].[IsAutoIncrement]) = @IsAutoIncrement'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'IsRequired' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsRequired], [O].[IsRequired]) IS NULL'
                ELSE IF @S_IsRequired IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsRequired], [O].[IsRequired]) = @IsRequired'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'IsListable' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsListable], [O].[IsListable]) IS NULL'
                ELSE IF @S_IsListable IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsListable], [O].[IsListable]) = @IsListable'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'IsFilterable' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsFilterable], [O].[IsFilterable]) IS NULL'
                ELSE IF @S_IsFilterable IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsFilterable], [O].[IsFilterable]) = @IsFilterable'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'IsEditable' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsEditable], [O].[IsEditable]) IS NULL'
                ELSE IF @S_IsEditable IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsEditable], [O].[IsEditable]) = @IsEditable'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'IsGridable' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsGridable], [O].[IsGridable]) IS NULL'
                ELSE IF @S_IsGridable IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsGridable], [O].[IsGridable]) = @IsGridable'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'IsEncrypted' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsEncrypted], [O].[IsEncrypted]) IS NULL'
                ELSE IF @S_IsEncrypted IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsEncrypted], [O].[IsEncrypted]) = @IsEncrypted'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'IsInWords' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsInWords], [O].[IsInWords]) IS NULL'
                ELSE IF @S_IsInWords IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsInWords], [O].[IsInWords]) = @IsInWords'
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Columns] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@TableId bigint,@DomainId bigint,@ReferenceTableId bigint,@Name nvarchar(25),@Alias nvarchar(25),@IsAutoIncrement bit,@IsRequired bit,@IsListable bit,@IsFilterable bit,@IsEditable bit,@IsGridable bit,@IsEncrypted bit,@IsInWords bit, @r BIGINT OUTPUT'
                                       ,@Id = @S_Id
                                       ,@TableId = @S_TableId
                                       ,@DomainId = @S_DomainId
                                       ,@ReferenceTableId = @S_ReferenceTableId
                                       ,@Name = @S_Name
                                       ,@Alias = @S_Alias
                                       ,@IsAutoIncrement = @S_IsAutoIncrement
                                       ,@IsRequired = @S_IsRequired
                                       ,@IsListable = @S_IsListable
                                       ,@IsFilterable = @S_IsFilterable
                                       ,@IsEditable = @S_IsEditable
                                       ,@IsGridable = @S_IsGridable
                                       ,@IsEncrypted = @S_IsEncrypted
                                       ,@IsInWords = @S_IsInWords
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [TableId]
                    ,CAST(NULL AS smallint) AS [Sequence]
                    ,CAST(NULL AS bigint) AS [DomainId]
                    ,CAST(NULL AS bigint) AS [ReferenceTableId]
                    ,CAST(NULL AS nvarchar(25)) AS [Name]
                    ,CAST(NULL AS nvarchar(25)) AS [Alias]
                    ,CAST(NULL AS nvarchar(50)) AS [Description]
                    ,CAST(NULL AS nvarchar(25)) AS [Title]
                    ,CAST(NULL AS nvarchar(25)) AS [Caption]
                    ,CAST(NULL AS nvarchar(max)) AS [Default]
                    ,CAST(NULL AS nvarchar(max)) AS [Minimum]
                    ,CAST(NULL AS nvarchar(max)) AS [Maximum]
                    ,CAST(NULL AS bit) AS [IsPrimarykey]
                    ,CAST(NULL AS bit) AS [IsAutoIncrement]
                    ,CAST(NULL AS bit) AS [IsRequired]
                    ,CAST(NULL AS bit) AS [IsListable]
                    ,CAST(NULL AS bit) AS [IsFilterable]
                    ,CAST(NULL AS bit) AS [IsEditable]
                    ,CAST(NULL AS bit) AS [IsGridable]
                    ,CAST(NULL AS bit) AS [IsEncrypted]
                    ,CAST(NULL AS bit) AS [IsInWords]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Column'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[TableId]
                              ,[T].[Sequence]
                              ,[T].[DomainId]
                              ,[T].[ReferenceTableId]
                              ,[T].[Name]
                              ,[T].[Alias]
                              ,[T].[Description]
                              ,[T].[Title]
                              ,[T].[Caption]
                              ,[T].[Default]
                              ,[T].[Minimum]
                              ,[T].[Maximum]
                              ,[T].[IsPrimarykey]
                              ,[T].[IsAutoIncrement]
                              ,[T].[IsRequired]
                              ,[T].[IsListable]
                              ,[T].[IsFilterable]
                              ,[T].[IsEditable]
                              ,[T].[IsGridable]
                              ,[T].[IsEncrypted]
                              ,[T].[IsInWords]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Columns] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Column'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[TableId]
                                  ,[O].[Sequence]
                                  ,[O].[DomainId]
                                  ,[O].[ReferenceTableId]
                                  ,[O].[Name]
                                  ,[O].[Alias]
                                  ,[O].[Description]
                                  ,[O].[Title]
                                  ,[O].[Caption]
                                  ,[O].[Default]
                                  ,[O].[Minimum]
                                  ,[O].[Maximum]
                                  ,[O].[IsPrimarykey]
                                  ,[O].[IsAutoIncrement]
                                  ,[O].[IsRequired]
                                  ,[O].[IsListable]
                                  ,[O].[IsFilterable]
                                  ,[O].[IsEditable]
                                  ,[O].[IsGridable]
                                  ,[O].[IsEncrypted]
                                  ,[O].[IsInWords]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Table' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Alias]
              ,[R].[Description]
              ,[R].[ParentTableId]
              ,[R].[IsLegacy]
              ,[R].[CurrentId]
            INTO [#Tables]
            FROM [#result] [T]
                INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[TableId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Tables] ON [#Tables](Id)
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[ParentTableId]
                  ,[R].[IsLegacy]
                  ,[R].[CurrentId]
                FROM [#Tables] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[ParentTableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        SELECT DISTINCT 'Domain' AS [Kind]
              ,[R].[Id]
              ,[R].[TypeId]
              ,[R].[MaskId]
              ,[R].[Name]
              ,[R].[Length]
              ,[R].[Decimals]
              ,[R].[ValidValues]
              ,[R].[Default]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[Codification]
            INTO [#Domains]
            FROM [#result] [T]
                INNER JOIN [dbo].[Domains] [R] ON [R].[Id] = [T].[DomainId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Domains] ON [#Domains](Id)
        SELECT DISTINCT 'Type' AS [Kind]
              ,[R].[Id]
              ,[R].[CategoryId]
              ,[R].[Name]
              ,[R].[MaxLength]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[AskLength]
              ,[R].[AskDecimals]
              ,[R].[AskPrimarykey]
              ,[R].[AskAutoincrement]
              ,[R].[AskFilterable]
              ,[R].[AskGridable]
              ,[R].[AskCodification]
              ,[R].[IsLikeable]
              ,[R].[IsActive]
            INTO [#Types]
            FROM [#Domains] [T]
                INNER JOIN [dbo].[Types] [R] ON [R].[Id] = [T].[TypeId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Types] ON [#Types](Id)
        SELECT DISTINCT 'Category' AS [Kind]
              ,[R].[Id]
              ,CAST([dbo].[NUMBER_IN_WORDS](CAST([R].[Id] AS tinyint)) AS NVARCHAR(MAX)) AS [IdInWords]
              ,[R].[Name]
              ,[R].[HtmlInputType]
              ,[R].[HtmlInputAlign]
              ,[R].[AskEncrypted]
              ,[R].[AskMask]
              ,[R].[AskListable]
              ,[R].[AskDefault]
              ,[R].[AskMinimum]
              ,[R].[AskMaximum]
              ,[R].[AskInWords]
            INTO [#Categories]
            FROM [#Types] [T]
                INNER JOIN [dbo].[Categories] [R] ON [R].[Id] = [T].[CategoryId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Categories] ON [#Categories](Id)
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[ParentTableId]
                  ,[R].[IsLegacy]
                  ,[R].[CurrentId]
                FROM [#result] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[ReferenceTableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[ParentTableId]
                  ,[R].[IsLegacy]
                  ,[R].[CurrentId]
                FROM [#Tables] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[ParentTableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[TableId]
                      ,[Sequence]
                      ,[DomainId]
                      ,[ReferenceTableId]
                      ,[Name]
                      ,[Alias]
                      ,[Description]
                      ,[Title]
                      ,[Caption]
                      ,[Default]
                      ,[Minimum]
                      ,[Maximum]
                      ,[IsPrimarykey]
                      ,[IsAutoIncrement]
                      ,[IsRequired]
                      ,[IsListable]
                      ,[IsFilterable]
                      ,[IsEditable]
                      ,[IsGridable]
                      ,[IsEncrypted]
                      ,[IsInWords]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Tables].* FROM [#Tables] AS [Tables] FOR JSON PATH), '[]') AS [Tables]
              ,ISNULL((SELECT [Domains].* FROM [#Domains] AS [Domains] FOR JSON PATH), '[]') AS [Domains]
              ,ISNULL((SELECT [Types].* FROM [#Types] AS [Types] FOR JSON PATH), '[]') AS [Types]
              ,ISNULL((SELECT [Categories].* FROM [#Categories] AS [Categories] FOR JSON PATH), '[]') AS [Categories]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[IndexValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[IndexValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[IndexValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[IndexValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS bigint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Indexes] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em Indexes', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Indexes'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em Indexes', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Indexes]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [TableId] = JSON_VALUE(@LastRecord, '$.TableId')
                                  AND [Name] = JSON_VALUE(@LastRecord, '$.Name')
                                  AND [IsUnique] = JSON_VALUE(@LastRecord, '$.IsUnique'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Indexes'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.TableId') = JSON_VALUE(@LastRecord, '$.TableId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') = JSON_VALUE(@LastRecord, '$.Name')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsUnique') = JSON_VALUE(@LastRecord, '$.IsUnique'))
                THROW 51000, 'Registro de Indexes alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[Indexkeys] WHERE [IndexId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Indexkeys', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_TableId bigint = CAST(JSON_VALUE(@ActualRecord, '$.TableId') AS bigint)
                   ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))
                   ,@W_IsUnique bit = CAST(JSON_VALUE(@ActualRecord, '$.IsUnique') AS bit)

            IF @W_TableId IS NULL
                THROW 51000, 'Valor de TableId em @ActualRecord é requerido.', 1
            IF @W_TableId < CAST('1' AS bigint)
                THROW 51000, 'Valor de TableId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF NOT EXISTS(SELECT 1 FROM [dbo].[Tables] WHERE [Id] = @W_TableId)
                THROW 51000, 'Valor de TableId em @ActualRecord inexiste em Tables', 1
            IF @W_Name IS NULL
                THROW 51000, 'Valor de Name em @ActualRecord é requerido.', 1
            IF @W_IsUnique IS NULL
                THROW 51000, 'Valor de IsUnique em @ActualRecord é requerido.', 1
            IF @Action = 'create' BEGIN
                IF EXISTS(SELECT 1 FROM [dbo].[Indexes] WHERE [Name] = @W_Name)
                    THROW 51000, 'Chave única de UNQ_Indexes_Name já existe', 1
            ELSE IF EXISTS(SELECT 1 FROM [dbo].[Indexes] WHERE [Name] = @W_Name AND [Id] <> @W_Id)
                THROW 51000, 'Chave única de UNQ_Indexes_Name já existe', 1
            END
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[IndexPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[IndexPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[IndexPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[IndexPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id bigint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Indexes'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Indexes', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[IndexValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Indexes'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Indexes'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[IndexValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[IndexCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[IndexCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[IndexCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[IndexCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Indexes'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[IndexValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        DECLARE @W_TableId bigint = CAST(JSON_VALUE(@ActualRecord, '$.TableId') AS bigint)
               ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))
               ,@W_IsUnique bit = CAST(JSON_VALUE(@ActualRecord, '$.IsUnique') AS bit)

        INSERT INTO [dbo].[Indexes] ([Id]
                                            ,[TableId]
                                            ,[Name]
                                            ,[IsUnique]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_TableId
                                             ,@W_Name
                                             ,@W_IsUnique
                                             ,GETDATE()
                                             ,@UserName)
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

