/**********************************************************************************
Criar stored procedure [dbo].[IndexesRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[IndexesRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[IndexesRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[IndexesRead](@Login NVARCHAR(MAX)
                                          ,@RecordFilterGrid NVARCHAR(MAX)
                                          ,@RecordFilterTable NVARCHAR(MAX)
                                          ,@RecordSearch NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @LoginId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @LoginId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @LoginId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    IF @RecordFilterGrid IS NULL
            SET @RecordFilterGrid = '{}'
        ELSE IF ISJSON(@RecordFilterGrid) = 0
            THROW 51000, 'Valor de @RecordFilterGrid não está no formato JSON', 1
        IF @RecordFilterTable IS NULL
            SET @RecordFilterTable = '{}'
        ELSE IF ISJSON(@RecordFilterTable) = 0
            THROW 51000, 'Valor de @RecordFilterTable não está no formato JSON', 1
        IF @RecordSearch IS NOT NULL AND ISJSON(@RecordSearch) = 0
            THROW 51000, 'Valor de @RecordSearch não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Indexes') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
            IF CHARINDEX('[T].[Id]', @OrderBy) = 0
                SET @OrderBy = @OrderBy + ', [T].[Id] ASC'
        END
        IF @IsActionList = 1
            SET @OrderBy = '[T].[Name] ASC, [T].[Id] ASC'
        DECLARE @PickerValue nvarchar(50) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @LoginId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.TableId') AS bigint) AS [TableId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(50)) AS [Name]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsUnique') AS bit) AS [IsUnique]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Indexes'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@RecordFilterGrid, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@RecordFilterTable, '$.Id') AS bigint)
               ,@WT_TableId bigint = CAST(JSON_VALUE(@RecordFilterTable, '$.TableId') AS bigint)
               ,@WT_Name nvarchar(50) = CAST(JSON_VALUE(@RecordFilterTable, '$.Name') AS nvarchar(50))
               ,@WT_IsUnique bit = CAST(JSON_VALUE(@RecordFilterTable, '$.IsUnique') AS bit)

        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Id' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Id] IS NULL'
        ELSE IF @WT_Id IS NOT NULL BEGIN
            IF @WT_Id < CAST('1' AS bigint)
                THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'TableId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[TableId] IS NULL'
        ELSE IF @WT_TableId IS NOT NULL BEGIN
            IF @WT_TableId < CAST('1' AS bigint)
                THROW 51000, 'Valor de TableId deve ser maior que ou igual a ''1''', 1
            SET @Where = @Where + ' AND [T].[TableId] = @T_TableId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Name' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Name] IS NULL'
        ELSE IF @WT_Name IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Name] = @T_Name'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'IsUnique' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[IsUnique] IS NULL'
        ELSE IF @WT_IsUnique IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[IsUnique] = @T_IsUnique'
        END
        IF @IsActionList = 1 BEGIN
            SET @PickerValue = CAST(JSON_VALUE(@RecordFilterGrid, '$.Picker.Value') AS nvarchar(50))
            IF @PickerValue IS NULL
                SET @PickerValue = ''
            SET @Where = @Where + ' AND [T].[Name] LIKE ''%'' + @PickerValue + ''%'''
        END ELSE IF @_ IS NULL BEGIN
            DECLARE @W_Id bigint = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.Id') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.Id') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.Id') AS bigint))
                   ,@W_TableId bigint = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.TableId') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.TableId') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.TableId') AS bigint))
                   ,@W_Name nvarchar(50) = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.Name') AS nvarchar(50)), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.Name') AS nvarchar(50)), CAST(JSON_VALUE(@RecordFilterGrid, '$.Name') AS nvarchar(50)))
                   ,@W_IsUnique bit = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.IsUnique') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.IsUnique') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.IsUnique') AS bit))

            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'Id' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[Id] IS NULL'
            ELSE IF @W_Id IS NOT NULL BEGIN
                IF @W_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @Where = @Where + ' AND [T].[Id] = @Id'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'TableId' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'TableId' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'TableId' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'TableId' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[TableId] IS NULL'
            ELSE IF @W_TableId IS NOT NULL BEGIN
                IF @W_TableId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de TableId deve ser maior que ou igual a ''1''', 1
                SET @Where = @Where + ' AND [T].[TableId] = @TableId'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'Name' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'Name' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Name' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'Name' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[Name] IS NULL'
            ELSE IF @W_Name IS NOT NULL BEGIN
                SET @Where = @Where + ' AND [T].[Name] = @Name'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'IsUnique' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'IsUnique' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'IsUnique' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'IsUnique' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[IsUnique] IS NULL'
            ELSE IF @W_IsUnique IS NOT NULL BEGIN
                SET @Where = @Where + ' AND [T].[IsUnique] = @IsUnique'
            END
        END ELSE
            SET @Where = @Where + ' AND [T].[Id] IN (' + @_ + ')'
        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                                        ,[T].[Id]
                                    FROM [dbo].[Indexes] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [#].[Id] = [T].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                                        ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @IsActionList = 1 BEGIN
            EXEC sp_executesql @sql
                               ,N'@PickerValue nvarchar(50),@T_Id bigint,@T_TableId bigint,@T_Name nvarchar(50),@T_IsUnique bit'
                               ,@PickerValue = @PickerValue
                               ,@T_Id = @WT_Id
                               ,@T_TableId = @WT_TableId
                               ,@T_Name = @WT_Name
                               ,@T_IsUnique = @WT_IsUnique
        END ELSE IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_TableId bigint,@T_Name nvarchar(50),@T_IsUnique bit,@Id bigint,@TableId bigint,@Name nvarchar(50),@IsUnique bit'
                               ,@T_Id = @WT_Id
                               ,@T_TableId = @WT_TableId
                               ,@T_Name = @WT_Name
                               ,@T_IsUnique = @WT_IsUnique
                               ,@Id = @W_Id
                               ,@TableId = @W_TableId
                               ,@Name = @W_Name
                               ,@IsUnique = @W_IsUnique
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_TableId bigint,@T_Name nvarchar(50),@T_IsUnique bit'
                               ,@T_Id = @WT_Id
                               ,@T_TableId = @WT_TableId
                               ,@T_Name = @WT_Name
                               ,@T_IsUnique = @WT_IsUnique
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            DECLARE @SearchRecno BIGINT = NULL
            IF @RecordSearch IS NOT NULL BEGIN
                DECLARE @Recno BIGINT
                       ,@S_Id bigint = CAST(JSON_VALUE(@RecordSearch, '$.Id') AS bigint)
                       ,@S_TableId bigint = CAST(JSON_VALUE(@RecordSearch, '$.TableId') AS bigint)
                       ,@S_Name nvarchar(50) = CAST(JSON_VALUE(@RecordSearch, '$.Name') AS nvarchar(50))
                       ,@S_IsUnique bit = CAST(JSON_VALUE(@RecordSearch, '$.IsUnique') AS bit)

                SET @Where = ''
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'Id' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Id], [O].[Id]) IS NULL'
                ELSE IF @S_Id IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Id], [O].[Id]) = @Id'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'TableId' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[TableId], [O].[TableId]) IS NULL'
                ELSE IF @S_TableId IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[TableId], [O].[TableId]) = @TableId'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'Name' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Name], [O].[Name]) IS NULL'
                ELSE IF @S_Name IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Name], [O].[Name]) LIKE ''%'' + @Name + ''%'''
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'IsUnique' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsUnique], [O].[IsUnique]) IS NULL'
                ELSE IF @S_IsUnique IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsUnique], [O].[IsUnique]) = @IsUnique'
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Indexes] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@TableId bigint,@Name nvarchar(50),@IsUnique bit, @r BIGINT OUTPUT'
                                       ,@Id = @S_Id
                                       ,@TableId = @S_TableId
                                       ,@Name = @S_Name
                                       ,@IsUnique = @S_IsUnique
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [TableId]
                    ,CAST(NULL AS nvarchar(50)) AS [Name]
                    ,CAST(NULL AS bit) AS [IsUnique]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Index'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[TableId]
                              ,[T].[Name]
                              ,[T].[IsUnique]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Indexes] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Index'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[TableId]
                                  ,[O].[Name]
                                  ,[O].[IsUnique]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Table' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Alias]
              ,[R].[Description]
              ,[R].[ParentTableId]
              ,[R].[IsLegacy]
              ,[R].[CurrentId]
            INTO [#Tables]
            FROM [#result] [T]
                INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[TableId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Tables] ON [#Tables](Id)
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[ParentTableId]
                  ,[R].[IsLegacy]
                  ,[R].[CurrentId]
                FROM [#Tables] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[ParentTableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[TableId]
                      ,[Name]
                      ,[Name] AS [ListItemValue]
                      ,[IsUnique]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Tables].* FROM [#Tables] AS [Tables] FOR JSON PATH), '[]') AS [Tables]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[IndexkeyValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[IndexkeyValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[IndexkeyValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[IndexkeyValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS bigint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Indexkeys] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em Indexkeys', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Indexkeys'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em Indexkeys', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Indexkeys]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [IndexId] = JSON_VALUE(@LastRecord, '$.IndexId')
                                  AND [Sequence] = JSON_VALUE(@LastRecord, '$.Sequence')
                                  AND [ColumnId] = JSON_VALUE(@LastRecord, '$.ColumnId')
                                  AND [IsDescending] = JSON_VALUE(@LastRecord, '$.IsDescending'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Indexkeys'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IndexId') = JSON_VALUE(@LastRecord, '$.IndexId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Sequence') = JSON_VALUE(@LastRecord, '$.Sequence')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ColumnId') = JSON_VALUE(@LastRecord, '$.ColumnId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsDescending') = JSON_VALUE(@LastRecord, '$.IsDescending'))
                THROW 51000, 'Registro de Indexkeys alterado por outro usuário', 1
        END

        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_IndexId bigint = CAST(JSON_VALUE(@ActualRecord, '$.IndexId') AS bigint)
                   ,@W_Sequence smallint = CAST(JSON_VALUE(@ActualRecord, '$.Sequence') AS smallint)
                   ,@W_ColumnId bigint = CAST(JSON_VALUE(@ActualRecord, '$.ColumnId') AS bigint)
                   ,@W_IsDescending bit = CAST(JSON_VALUE(@ActualRecord, '$.IsDescending') AS bit)

            IF @W_IndexId IS NULL
                THROW 51000, 'Valor de IndexId em @ActualRecord é requerido.', 1
            IF @W_IndexId < CAST('1' AS bigint)
                THROW 51000, 'Valor de IndexId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF NOT EXISTS(SELECT 1 FROM [dbo].[Indexes] WHERE [Id] = @W_IndexId)
                THROW 51000, 'Valor de IndexId em @ActualRecord inexiste em Indexes', 1
            IF @W_Sequence IS NULL
                THROW 51000, 'Valor de Sequence em @ActualRecord é requerido.', 1
            IF @W_Sequence < CAST('1' AS smallint)
                THROW 51000, 'Valor de Sequence em @ActualRecord deve ser maior que ou igual a 1', 1
            IF @W_ColumnId IS NULL
                THROW 51000, 'Valor de ColumnId em @ActualRecord é requerido.', 1
            IF @W_ColumnId < CAST('1' AS bigint)
                THROW 51000, 'Valor de ColumnId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF NOT EXISTS(SELECT 1 FROM [dbo].[Columns] WHERE [Id] = @W_ColumnId)
                THROW 51000, 'Valor de ColumnId em @ActualRecord inexiste em Columns', 1
            IF @W_IsDescending IS NULL
                THROW 51000, 'Valor de IsDescending em @ActualRecord é requerido.', 1
            IF @Action = 'create' BEGIN
                IF EXISTS(SELECT 1 FROM [dbo].[Indexkeys] WHERE [IndexId] = @W_IndexId AND [Sequence] = @W_Sequence)
                    THROW 51000, 'Chave única de UNQ_Indexkeys_IndexId_Sequence já existe', 1
                IF EXISTS(SELECT 1 FROM [dbo].[Indexkeys] WHERE [IndexId] = @W_IndexId AND [ColumnId] = @W_ColumnId)
                    THROW 51000, 'Chave única de UNQ_Indexkeys_IndexId_ColumnId já existe', 1
            ELSE IF EXISTS(SELECT 1 FROM [dbo].[Indexkeys] WHERE [IndexId] = @W_IndexId AND [Sequence] = @W_Sequence AND [Id] <> @W_Id)
                THROW 51000, 'Chave única de UNQ_Indexkeys_IndexId_Sequence já existe', 1
            ELSE IF EXISTS(SELECT 1 FROM [dbo].[Indexkeys] WHERE [IndexId] = @W_IndexId AND [ColumnId] = @W_ColumnId AND [Id] <> @W_Id)
                THROW 51000, 'Chave única de UNQ_Indexkeys_IndexId_ColumnId já existe', 1
            END
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[IndexkeyPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[IndexkeyPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[IndexkeyPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[IndexkeyPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id bigint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Indexkeys'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Indexkeys', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[IndexkeyValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Indexkeys'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Indexkeys'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[IndexkeyValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[IndexkeyCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[IndexkeyCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[IndexkeyCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[IndexkeyCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Indexkeys'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[IndexkeyValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        DECLARE @W_IndexId bigint = CAST(JSON_VALUE(@ActualRecord, '$.IndexId') AS bigint)
               ,@W_Sequence smallint = CAST(JSON_VALUE(@ActualRecord, '$.Sequence') AS smallint)
               ,@W_ColumnId bigint = CAST(JSON_VALUE(@ActualRecord, '$.ColumnId') AS bigint)
               ,@W_IsDescending bit = CAST(JSON_VALUE(@ActualRecord, '$.IsDescending') AS bit)

        INSERT INTO [dbo].[Indexkeys] ([Id]
                                            ,[IndexId]
                                            ,[Sequence]
                                            ,[ColumnId]
                                            ,[IsDescending]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_IndexId
                                             ,@W_Sequence
                                             ,@W_ColumnId
                                             ,@W_IsDescending
                                             ,GETDATE()
                                             ,@UserName)
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

