/**********************************************************************************
Criar stored procedure [dbo].[SessionsRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SessionsRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SessionsRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SessionsRead](@Login NVARCHAR(MAX)
                                          ,@RecordFilterGrid NVARCHAR(MAX)
                                          ,@RecordFilterTable NVARCHAR(MAX)
                                          ,@RecordSearch NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @LoginId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @LoginId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @LoginId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    IF @RecordFilterGrid IS NULL
            SET @RecordFilterGrid = '{}'
        ELSE IF ISJSON(@RecordFilterGrid) = 0
            THROW 51000, 'Valor de @RecordFilterGrid não está no formato JSON', 1
        IF @RecordFilterTable IS NULL
            SET @RecordFilterTable = '{}'
        ELSE IF ISJSON(@RecordFilterTable) = 0
            THROW 51000, 'Valor de @RecordFilterTable não está no formato JSON', 1
        IF @RecordSearch IS NOT NULL AND ISJSON(@RecordSearch) = 0
            THROW 51000, 'Valor de @RecordSearch não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Sessions') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
            IF CHARINDEX('[T].[Id]', @OrderBy) = 0
                SET @OrderBy = @OrderBy + ', [T].[Id] ASC'
        END

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @LoginId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SystemId') AS bigint) AS [SystemId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.UserId') AS bigint) AS [UserId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ClientRsaPublicKey') AS nvarchar(512)) AS [ClientRsaPublicKey]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.PublicKey') AS nvarchar(256)) AS [PublicKey]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsLogged') AS bit) AS [IsLogged]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Sessions'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@RecordFilterGrid, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@RecordFilterTable, '$.Id') AS bigint)
               ,@WT_SystemId bigint = CAST(JSON_VALUE(@RecordFilterTable, '$.SystemId') AS bigint)
               ,@WT_UserId bigint = CAST(JSON_VALUE(@RecordFilterTable, '$.UserId') AS bigint)
               ,@WT_IsLogged bit = CAST(JSON_VALUE(@RecordFilterTable, '$.IsLogged') AS bit)

        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Id' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Id] IS NULL'
        ELSE IF @WT_Id IS NOT NULL BEGIN
            IF @WT_Id < CAST('1' AS bigint)
                THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'SystemId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[SystemId] IS NULL'
        ELSE IF @WT_SystemId IS NOT NULL BEGIN
            IF @WT_SystemId < CAST('1' AS bigint)
                THROW 51000, 'Valor de SystemId deve ser maior que ou igual a ''1''', 1
            SET @Where = @Where + ' AND [T].[SystemId] = @T_SystemId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'UserId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[UserId] IS NULL'
        ELSE IF @WT_UserId IS NOT NULL BEGIN
            IF @WT_UserId < CAST('1' AS bigint)
                THROW 51000, 'Valor de UserId deve ser maior que ou igual a ''1''', 1
            SET @Where = @Where + ' AND [T].[UserId] = @T_UserId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'IsLogged' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[IsLogged] IS NULL'
        ELSE IF @WT_IsLogged IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[IsLogged] = @T_IsLogged'
        END
        IF @_ IS NULL BEGIN
            DECLARE @W_Id bigint = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.Id') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.Id') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.Id') AS bigint))
                   ,@W_SystemId bigint = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.SystemId') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.SystemId') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.SystemId') AS bigint))
                   ,@W_UserId bigint = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.UserId') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.UserId') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.UserId') AS bigint))
                   ,@W_IsLogged bit = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.IsLogged') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.IsLogged') AS bit), CAST(JSON_VALUE(@RecordFilterGrid, '$.IsLogged') AS bit))

            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'Id' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[Id] IS NULL'
            ELSE IF @W_Id IS NOT NULL BEGIN
                IF @W_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @Where = @Where + ' AND [T].[Id] = @Id'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'SystemId' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'SystemId' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'SystemId' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'SystemId' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[SystemId] IS NULL'
            ELSE IF @W_SystemId IS NOT NULL BEGIN
                IF @W_SystemId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de SystemId deve ser maior que ou igual a ''1''', 1
                SET @Where = @Where + ' AND [T].[SystemId] = @SystemId'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'UserId' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'UserId' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'UserId' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'UserId' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[UserId] IS NULL'
            ELSE IF @W_UserId IS NOT NULL BEGIN
                IF @W_UserId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de UserId deve ser maior que ou igual a ''1''', 1
                SET @Where = @Where + ' AND [T].[UserId] = @UserId'
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'IsLogged' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'IsLogged' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'IsLogged' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'IsLogged' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[IsLogged] IS NULL'
            ELSE IF @W_IsLogged IS NOT NULL BEGIN
                SET @Where = @Where + ' AND [T].[IsLogged] = @IsLogged'
            END
        END ELSE
            SET @Where = @Where + ' AND [T].[Id] IN (' + @_ + ')'
        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                                        ,[T].[Id]
                                    FROM [dbo].[Sessions] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [#].[Id] = [T].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                                        ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_SystemId bigint,@T_UserId bigint,@T_IsLogged bit,@Id bigint,@SystemId bigint,@UserId bigint,@IsLogged bit'
                               ,@T_Id = @WT_Id
                               ,@T_SystemId = @WT_SystemId
                               ,@T_UserId = @WT_UserId
                               ,@T_IsLogged = @WT_IsLogged
                               ,@Id = @W_Id
                               ,@SystemId = @W_SystemId
                               ,@UserId = @W_UserId
                               ,@IsLogged = @W_IsLogged
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_SystemId bigint,@T_UserId bigint,@T_IsLogged bit'
                               ,@T_Id = @WT_Id
                               ,@T_SystemId = @WT_SystemId
                               ,@T_UserId = @WT_UserId
                               ,@T_IsLogged = @WT_IsLogged
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            DECLARE @SearchRecno BIGINT = NULL
            IF @RecordSearch IS NOT NULL BEGIN
                DECLARE @Recno BIGINT
                       ,@S_Id bigint = CAST(JSON_VALUE(@RecordSearch, '$.Id') AS bigint)
                       ,@S_SystemId bigint = CAST(JSON_VALUE(@RecordSearch, '$.SystemId') AS bigint)
                       ,@S_UserId bigint = CAST(JSON_VALUE(@RecordSearch, '$.UserId') AS bigint)
                       ,@S_IsLogged bit = CAST(JSON_VALUE(@RecordSearch, '$.IsLogged') AS bit)

                SET @Where = ''
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'Id' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Id], [O].[Id]) IS NULL'
                ELSE IF @S_Id IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Id], [O].[Id]) = @Id'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'SystemId' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[SystemId], [O].[SystemId]) IS NULL'
                ELSE IF @S_SystemId IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[SystemId], [O].[SystemId]) = @SystemId'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'UserId' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[UserId], [O].[UserId]) IS NULL'
                ELSE IF @S_UserId IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[UserId], [O].[UserId]) = @UserId'
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'IsLogged' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsLogged], [O].[IsLogged]) IS NULL'
                ELSE IF @S_IsLogged IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[IsLogged], [O].[IsLogged]) = @IsLogged'
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Sessions] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@SystemId bigint,@UserId bigint,@IsLogged bit, @r BIGINT OUTPUT'
                                       ,@Id = @S_Id
                                       ,@SystemId = @S_SystemId
                                       ,@UserId = @S_UserId
                                       ,@IsLogged = @S_IsLogged
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [SystemId]
                    ,CAST(NULL AS bigint) AS [UserId]
                    ,CAST(NULL AS nvarchar(512)) AS [ClientRsaPublicKey]
                    ,CAST(NULL AS nvarchar(256)) AS [PublicKey]
                    ,CAST(NULL AS bit) AS [IsLogged]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Session'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[SystemId]
                              ,[T].[UserId]
                              ,[T].[ClientRsaPublicKey]
                              ,[T].[PublicKey]
                              ,[T].[IsLogged]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Sessions] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Session'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[SystemId]
                                  ,[O].[UserId]
                                  ,[O].[ClientRsaPublicKey]
                                  ,[O].[PublicKey]
                                  ,[O].[IsLogged]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'System' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Description]
              ,[R].[ClientName]
              ,[R].[MaxRetryLogins]
              ,[R].[IsOffAir]
            INTO [#Systems]
            FROM [#result] [T]
                INNER JOIN [dbo].[Systems] [R] ON [R].[Id] = [T].[SystemId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Systems] ON [#Systems](Id)
        SELECT DISTINCT 'User' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Password]
              ,[R].[FullName]
              ,[R].[RetryLogins]
              ,[R].[IsActive]
            INTO [#Users]
            FROM [#result] [T]
                INNER JOIN [dbo].[Users] [R] ON [R].[Id] = [T].[UserId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Users] ON [#Users](Id)
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[SystemId]
                      ,[UserId]
                      ,[ClientRsaPublicKey]
                      ,[PublicKey]
                      ,[IsLogged]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Systems].* FROM [#Systems] AS [Systems] FOR JSON PATH), '[]') AS [Systems]
              ,ISNULL((SELECT [Users].* FROM [#Users] AS [Users] FOR JSON PATH), '[]') AS [Users]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TransactionValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TransactionValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TransactionValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TransactionValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS bigint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em Transactions', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Transactions'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em Transactions', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Transactions]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [SessionId] = JSON_VALUE(@LastRecord, '$.SessionId')
                                  AND [dbo].[IS_EQUAL]([IsConfirmed], JSON_VALUE(@LastRecord, '$.IsConfirmed'), 'bit') = 1)
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Transactions'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SessionId') = JSON_VALUE(@LastRecord, '$.SessionId')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsConfirmed'), JSON_VALUE(@LastRecord, '$.IsConfirmed'), 'bit') = 1)
                THROW 51000, 'Registro de Transactions alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[Operations] WHERE [TransactionId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Operations', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_SessionId bigint = CAST(JSON_VALUE(@ActualRecord, '$.SessionId') AS bigint)
                   ,@W_IsConfirmed bit = CAST(JSON_VALUE(@ActualRecord, '$.IsConfirmed') AS bit)

            IF @W_SessionId IS NULL
                THROW 51000, 'Valor de SessionId em @ActualRecord é requerido.', 1
            IF @W_SessionId < CAST('1' AS bigint)
                THROW 51000, 'Valor de SessionId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF NOT EXISTS(SELECT 1 FROM [dbo].[Sessions] WHERE [Id] = @W_SessionId)
                THROW 51000, 'Valor de SessionId em @ActualRecord inexiste em Sessions', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TransactionPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TransactionPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TransactionPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TransactionPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id bigint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Transactions'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Transactions', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[TransactionValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Transactions'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Transactions'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[TransactionValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TransactionsRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TransactionsRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TransactionsRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TransactionsRead](@Login NVARCHAR(MAX)
                                          ,@RecordFilterGrid NVARCHAR(MAX)
                                          ,@RecordFilterTable NVARCHAR(MAX)
                                          ,@RecordSearch NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @LoginId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @LoginId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @LoginId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    IF @RecordFilterGrid IS NULL
            SET @RecordFilterGrid = '{}'
        ELSE IF ISJSON(@RecordFilterGrid) = 0
            THROW 51000, 'Valor de @RecordFilterGrid não está no formato JSON', 1
        IF @RecordFilterTable IS NULL
            SET @RecordFilterTable = '{}'
        ELSE IF ISJSON(@RecordFilterTable) = 0
            THROW 51000, 'Valor de @RecordFilterTable não está no formato JSON', 1
        IF @RecordSearch IS NOT NULL AND ISJSON(@RecordSearch) = 0
            THROW 51000, 'Valor de @RecordSearch não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Transactions') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
            IF CHARINDEX('[T].[Id]', @OrderBy) = 0
                SET @OrderBy = @OrderBy + ', [T].[Id] ASC'
        END

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @LoginId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SessionId') AS bigint) AS [SessionId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsConfirmed') AS bit) AS [IsConfirmed]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Transactions'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@RecordFilterGrid, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@RecordFilterTable, '$.Id') AS bigint)

        IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Id' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Id] IS NULL'
        ELSE IF @WT_Id IS NOT NULL BEGIN
            IF @WT_Id < CAST('1' AS bigint)
                THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF @_ IS NULL BEGIN
            DECLARE @W_Id bigint = COALESCE(CAST(JSON_VALUE(@RecordFilterGrid, '$.Filter.Id') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.Fixed.Id') AS bigint), CAST(JSON_VALUE(@RecordFilterGrid, '$.Id') AS bigint))

            IF EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Filter') WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid, '$.Fixed') WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterTable) WHERE [key] = 'Id' AND [type] = 0)
               OR EXISTS(SELECT 1 FROM OPENJSON(@RecordFilterGrid) WHERE [key] = 'Id' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[Id] IS NULL'
            ELSE IF @W_Id IS NOT NULL BEGIN
                IF @W_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @Where = @Where + ' AND [T].[Id] = @Id'
            END
        END ELSE
            SET @Where = @Where + ' AND [T].[Id] IN (' + @_ + ')'
        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                                        ,[T].[Id]
                                    FROM [dbo].[Transactions] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [#].[Id] = [T].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                                        ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@Id bigint'
                               ,@T_Id = @WT_Id
                               ,@Id = @W_Id
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint'
                               ,@T_Id = @WT_Id
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            DECLARE @SearchRecno BIGINT = NULL
            IF @RecordSearch IS NOT NULL BEGIN
                DECLARE @Recno BIGINT
                       ,@S_Id bigint = CAST(JSON_VALUE(@RecordSearch, '$.Id') AS bigint)

                SET @Where = ''
                IF EXISTS(SELECT 1 FROM OPENJSON(@RecordSearch) WHERE [key] = 'Id' AND [type] = 0)
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Id], [O].[Id]) IS NULL'
                ELSE IF @S_Id IS NOT NULL
                    SET @Where = @Where + CASE WHEN @Where = '' THEN '' ELSE ' AND ' END + 'COALESCE([D].[Id], [O].[Id]) = @Id'
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Transactions] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint, @r BIGINT OUTPUT'
                                       ,@Id = @S_Id
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [SessionId]
                    ,CAST(NULL AS bit) AS [IsConfirmed]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Transaction'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[SessionId]
                              ,[T].[IsConfirmed]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Transactions] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Transaction'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[SessionId]
                                  ,[O].[IsConfirmed]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Session' AS [Kind]
              ,[R].[Id]
              ,[R].[SystemId]
              ,[R].[UserId]
              ,[R].[ClientRsaPublicKey]
              ,[R].[PublicKey]
              ,[R].[IsLogged]
            INTO [#Sessions]
            FROM [#result] [T]
                INNER JOIN [dbo].[Sessions] [R] ON [R].[Id] = [T].[SessionId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Sessions] ON [#Sessions](Id)
        SELECT DISTINCT 'System' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Description]
              ,[R].[ClientName]
              ,[R].[MaxRetryLogins]
              ,[R].[IsOffAir]
            INTO [#Systems]
            FROM [#Sessions] [T]
                INNER JOIN [dbo].[Systems] [R] ON [R].[Id] = [T].[SystemId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Systems] ON [#Systems](Id)
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[SessionId]
                      ,[IsConfirmed]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Sessions].* FROM [#Sessions] AS [Sessions] FOR JSON PATH), '[]') AS [Sessions]
              ,ISNULL((SELECT [Systems].* FROM [#Systems] AS [Systems] FOR JSON PATH), '[]') AS [Systems]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[OperationValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[OperationValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[OperationValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[OperationValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS bigint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Operations] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em Operations', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Operations'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em Operations', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [TransactionId] = JSON_VALUE(@LastRecord, '$.TransactionId')
                                  AND [TableName] = JSON_VALUE(@LastRecord, '$.TableName')
                                  AND [Action] = JSON_VALUE(@LastRecord, '$.Action')
                                  AND [dbo].[IS_EQUAL]([LastRecord], JSON_VALUE(@LastRecord, '$.LastRecord'), 'nvarchar(max)') = 1
                                  AND [ActualRecord] = JSON_VALUE(@LastRecord, '$.ActualRecord')
                                  AND [dbo].[IS_EQUAL]([IsConfirmed], JSON_VALUE(@LastRecord, '$.IsConfirmed'), 'bit') = 1)
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Operations'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.TransactionId') = JSON_VALUE(@LastRecord, '$.TransactionId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.TableName') = JSON_VALUE(@LastRecord, '$.TableName')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Action') = JSON_VALUE(@LastRecord, '$.Action')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.LastRecord'), JSON_VALUE(@LastRecord, '$.LastRecord'), 'nvarchar(max)') = 1
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ActualRecord') = JSON_VALUE(@LastRecord, '$.ActualRecord')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsConfirmed'), JSON_VALUE(@LastRecord, '$.IsConfirmed'), 'bit') = 1)
                THROW 51000, 'Registro de Operations alterado por outro usuário', 1
        END

        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_TransactionId bigint = CAST(JSON_VALUE(@ActualRecord, '$.TransactionId') AS bigint)
                   ,@W_TableName nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.TableName') AS nvarchar(25))
                   ,@W_Action nvarchar(15) = CAST(JSON_VALUE(@ActualRecord, '$.Action') AS nvarchar(15))
                   ,@W_LastRecord nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.LastRecord') AS nvarchar(max))
                   ,@W_ActualRecord nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.ActualRecord') AS nvarchar(max))
                   ,@W_IsConfirmed bit = CAST(JSON_VALUE(@ActualRecord, '$.IsConfirmed') AS bit)

            IF @W_TransactionId IS NULL
                THROW 51000, 'Valor de TransactionId em @ActualRecord é requerido.', 1
            IF @W_TransactionId < CAST('1' AS bigint)
                THROW 51000, 'Valor de TransactionId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @W_TransactionId)
                THROW 51000, 'Valor de TransactionId em @ActualRecord inexiste em Transactions', 1
            IF @W_TableName IS NULL
                THROW 51000, 'Valor de TableName em @ActualRecord é requerido.', 1
            IF @W_Action IS NULL
                THROW 51000, 'Valor de Action em @ActualRecord é requerido.', 1
            IF @W_ActualRecord IS NULL
                THROW 51000, 'Valor de ActualRecord em @ActualRecord é requerido.', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[OperationPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[OperationPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[OperationPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[OperationPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id bigint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Operations'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Operations', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[OperationValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Operations'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Operations'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[OperationValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[OperationCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[OperationCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[OperationCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[OperationCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Operations'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[OperationValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        DECLARE @W_TransactionId bigint = CAST(JSON_VALUE(@ActualRecord, '$.TransactionId') AS bigint)
               ,@W_TableName nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.TableName') AS nvarchar(25))
               ,@W_Action nvarchar(15) = CAST(JSON_VALUE(@ActualRecord, '$.Action') AS nvarchar(15))
               ,@W_LastRecord nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.LastRecord') AS nvarchar(max))
               ,@W_ActualRecord nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.ActualRecord') AS nvarchar(max))
               ,@W_IsConfirmed bit = CAST(JSON_VALUE(@ActualRecord, '$.IsConfirmed') AS bit)

        INSERT INTO [dbo].[Operations] ([Id]
                                            ,[TransactionId]
                                            ,[TableName]
                                            ,[Action]
                                            ,[LastRecord]
                                            ,[ActualRecord]
                                            ,[IsConfirmed]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_TransactionId
                                             ,@W_TableName
                                             ,@W_Action
                                             ,@W_LastRecord
                                             ,@W_ActualRecord
                                             ,@W_IsConfirmed
                                             ,GETDATE()
                                             ,@UserName)
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

